import json
from report_base import Report,ROOT

def build():
 r=Report(4,'Соглашение об уровне сервиса','','')
 r.heading('ЦЕЛЬ ПРАКТИЧЕСКОЙ РАБОТЫ')
 r.p('Цель работы: составить соглашение об уровне сервиса для ИТ-услуг ООО «ТехноСервис», определив границы обслуживания, состав и стоимость услуг, приоритеты, сроки реакции и решения, ответственность участников и порядок обработки обращений.')
 r.heading('ВЫПОЛНЕНИЕ РАБОТЫ')
 r.sub('Соглашение об уровне сервиса (SLA)')
 for text in ['Версия: 1.0. Номер: SLA-TS-2026.','Дата документа: 22.10.2026.','Поставщик услуг: ООО «ТехноСервис», основано 15 марта 2020 года.','Заказчик: организация, использующая услуги по согласованной спецификации. Представитель заказчика - уполномоченный сотрудник с зарегистрированной учётной записью.']:
  r.p(text)
 r.minor('1. Границы оказания услуг')
 r.p('Исполнитель предоставляет вычислительные ресурсы, лицензии и облачное хранилище, выполняет администрирование, мониторинг, поддержку и резервное копирование. Услуги относятся к двум линиям: «Доступ/аренда» и «Управление». Местоположение ресурсов, допустимые способы доступа и состав обслуживания фиксируются в спецификации. Географическое положение заказчика не ограничивает приём обращений при наличии канала связи.')
 r.p('Приём обращений и поддержка выполняются круглосуточно, 24 часа в сутки, 7 дней в неделю, включая выходные и праздники. Все сроки измеряются в календарных минутах и часах. Журнал хранится в UTC; уведомления и интерфейс показывают московское время (UTC+3).')
 r.p('Базовое обслуживание включает восстановление согласованной конфигурации. Разработка нового ПО, миграции, расширение ресурсов, закупки и обучение вне состава услуги оцениваются отдельно до начала работ. Соглашение является учебной моделью 2026 года; изменение его условий оформляется новой версией и не применяется к прошлым измерениям.')
 r.minor('2. Список, состав и стоимость предоставляемых услуг')
 services=json.loads((ROOT/'data/services.json').read_text())
 r.table('Состав и базовая стоимость услуг',['Услуга','Состав обслуживания','Стоимость'],[[s['name'],s['description'],s['price']] for s in services],[4.8,6,5.7])
 r.p('Все шесть наименований и тарифов сохранены из исходного каталога предприятия. Формулировка «от» обозначает минимальную цену: итоговая сумма зависит от согласованного объёма и конфигурации. Налоги, сторонние лицензии, дробное использование месяца и дополнительные работы определяются отдельными условиями договора.')
 r.minor('3. Единица измерения стоимости услуг Исполнителя')
 for text in ['Виртуальные серверы: комплект 1 vCPU, 1 ГБ RAM и 10 ГБ SSD в месяц; стоимость 500 руб. за комплект.','Лицензирование ПО: пользователь в месяц, от 1 000 руб.','Облачное хранилище: пакет 100 ГБ в месяц, от 200 руб.','Управление инфраструктурой: сервер в месяц, от 10 000 руб.','Мониторинг и поддержка: узел в месяц, от 5 000 руб.','Резервное копирование и восстановление: 1 ТБ в месяц, от 3 000 руб.']:
  r.bullet(text)
 r.p('Пример месячного расчёта по минимальным тарифам: 4 комплекта ВМ, 10 пользователей ПО, 5 пакетов хранилища, 2 сервера администрирования, 3 узла мониторинга и 2 ТБ копий: 500 × 4 + 1 000 × 10 + 200 × 5 + 10 000 × 2 + 5 000 × 3 + 3 000 × 2 = 54 000 руб. Почасовые ставки и надбавки за выходные в исходном каталоге не определены.')
 r.minor('4. Применяемый инструментарий')
 r.p('Программные и аппаратные средства соответствуют сервисно-ресурсным моделям предприятия. Обозначение через косую черту указывает допустимые альтернативы продуктов.')
 r.table('Средства предоставления и сопровождения услуг',['Услуга','ПО и данные','Оборудование'],[
 ['Аренда ВМ','VMware vSphere, БД конфигураций','Гипервизор, сервер БД, СХД и сеть'],
 ['Лицензирование','FlexLM/KMS, БД лицензий','Сервер лицензий и сервер БД'],
 ['Хранилище','Веб-интерфейс/API, БД метаданных','СХД, сервер приложений, сервер БД'],
 ['Администрирование','Ansible/SCCM, БД конфигураций и изменений','Управляемые серверы, сервер управления'],
 ['Мониторинг','Zabbix/Prometheus, агенты, БД метрик','Агенты серверов приложений и БД, сервер БД мониторинга'],
 ['Резервное копирование','Veeam, БД каталога копий','Сервер бэкапов, сервер БД, СХД копий']],[4,6,6.5])
 r.p('Телекоммуникации: защищённый удалённый доступ, сеть ЦОД и согласованные каналы заказчика. Основной канал учёта - Service Desk; телефон используется при аварийной недоступности портала, электронная почта и личные сообщения - для вспомогательного взаимодействия. Оператор переносит аварийные обращения в систему с подтверждённым временем первого поступления.')
 r.p('Человеческие ресурсы: инженер аренды и специалист лицензирования отдела аренды и доступа; системный администратор и инженер мониторинга отдела управления и поддержки; разработчик и аналитик отдела развития. Финансово-административный отдел обеспечивает расчёты, договоры и дежурства. Общую ответственность за SLA несёт руководитель отдела управления и поддержки, спорные вопросы утверждает глава предприятия.')
 r.p('Документация: каталог, SLA, спецификации, инструкции ИБ, регламенты инцидентов и изменений, журналы конфигураций и восстановления. Внешние ЦОД, операторы связи и вендоры привлекаются при наличии договора; ответственность за коммуникацию с заказчиком сохраняет поставщик услуги.')
 r.minor('5. Приоритеты задач')
 r.p('Приоритет определяется влиянием сбоя на бизнес и срочностью восстановления. Плановые запросы на ресурсы и изменения имеют отдельно согласованные сроки и не приравниваются к аварийному инциденту.')
 for text in ['P1 - критический: остановка критичного процесса без обходного пути, например недоступность производственной ВМ.','P2 - высокий: значительная деградация или отказ важного компонента с ограниченным обходным решением.','P3 - средний: локальный сбой с рабочим обходным путём; часть пользователей сохраняет доступ.','P4 - низкий: некритичная неисправность или консультационный инцидент без существенного влияния.']:
  r.bullet(text)
 r.minor('6. Выполнение задач в рамках одного приоритета')
 r.p('Внутри одного приоритета действует FIFO: сначала более раннее время регистрации, при равенстве - меньший номер обращения. Отступление от очереди допускается при подтверждённой зависимости работ и фиксируется руководителем поддержки в истории с обоснованием. Передача между специалистами не сбрасывает сроки.')
 r.p('P1 немедленно эскалируется руководителю поддержки. Для остальных приоритетов предупреждение о риске нарушения направляется при использовании 75 % срока решения. Дополнительные ресурсы и привлечение профильных специалистов согласуются через руководителя с сохранением единой карточки.')
 r.minor('7. Определение приоритетов Заказчиком')
 r.p('При регистрации заказчик выбирает исходный приоритет и описывает влияние, затронутую услугу и ресурсы. Поддержка проверяет обоснование. Изменение приоритета требует причины; старое и новое значения, автор и время сохраняются в журнале. Новый дедлайн рассчитывается от первоначальной регистрации.')
 r.p('Заказчик вправе запросить пересмотр приоритета в карточке обращения. До разрешения спора руководителем поддержки применяется более высокий обоснованный приоритет. Изменение функциональности и дополнительные работы согласуются отдельно и не изменяют показатели уже завершённых инцидентов.')
 r.minor('8. Уровни поддержки, сроки реакции и решения')
 r.table('Целевые сроки обслуживания 24/7',['Приоритет','Срок реакции','Срок решения','Обновление информации'],[
 ['P1','15 минут','4 часа','Не реже раза в час'],['P2','30 минут','8 часов','Не реже раза в 2 часа'],['P3','2 часа','24 часа','Не реже раза в сутки'],['P4','4 часа','72 часа','Не реже раза в сутки']],[3,4,4,5.5])
 r.p('Реакция - содержательное принятие специалистом с фиксацией первого действия. Автоматическое уведомление реакцией не считается. Решение - восстановление согласованной работоспособности или принятый заказчиком обходной путь с описанием действий. Время от регистрации до реакции и решения отсчитывается непрерывно; ожидание ответа и эскалация его не останавливают.')
 r.table('Распределение уровней поддержки',['Уровень','Исполнители','Содержание работ'],[
 ['L1','Дежурная поддержка, инженер мониторинга','Регистрация, уточнение влияния, типовые проверки, передача диагностических данных'],
 ['L2','Системный администратор, инженер аренды, специалист лицензирования','Профильная диагностика, восстановление конфигурации, проверка связанных КЕ'],
 ['L3','Разработчик, аналитик, внешний вендор по договору','Анализ сложного дефекта, исправление или обходное решение']],[2,6,8.5])
 r.p('Передача на следующий уровень содержит диагноз, журналы, выполненные действия и список ресурсов. До подтверждения приёма ответственность сохраняет передающий сотрудник. При недостатке ресурсов организационная эскалация направляется руководителю поддержки, затем главе предприятия.')
 r.p('Учебные цели качества: доступность ВМ, лицензирования, хранилища и системы мониторинга не ниже 99,5 % за месяц; выдача лицензии до 1 календарного дня после согласования; сбор метрик с интервалом до 60 секунд; журналирование 100 % согласованных изменений; успешность заданий копирования не ниже 98 %, RPO до 24 часов и RTO до 8 часов при наличии исправной копии.')
 r.p('Доступность A = 100 × (T - M - D) / (T - M), где T - календарные минуты месяца, M - согласованное обслуживание, D - подтверждённый незапланированный простой. Плановые работы объявляются за 48 часов, исключаемый интервал ограничен 120 минутами за месяц. При T = 43 200 и M = 0 цель 99,5 % допускает 216 минут простоя.')
 r.minor('9. Статусы обращений и их значения')
 r.table('Жизненный цикл обращения',['Статус','Значение','Следующий статус'],[
 ['Новая','Зарегистрировано; срок отсчитывается','В работе'],['В работе','Назначение, диагностика, восстановление','Ожидание; Решена'],['Ожидание','Необходимы данные или согласование; время продолжается','В работе'],['Решена','Исполнитель описал результат и время восстановления','Закрыта; В работе'],['Закрыта','Заказчик принял результат; доступно чтение','Переходов нет']],[3,8.5,5])
 r.p('При отказе от решения заказчик возвращает обращение в работу. История сохраняется, время окончательного решения пересчитывается от первоначальной регистрации. Автоматическое закрытие по отсутствию ответа не применяется. Повторный сбой после закрытия оформляется новым связанным обращением.')
 r.minor('10. Работа с распределенными проектами')
 r.p('Для распределённой команды определяются координаторы сторон, часовые пояса, ресурсы и разрешённые способы доступа. Единым источником состояния является карточка обращения. Переписка из других каналов переносится ответственным сотрудником; технические пароли и персональные данные не размещаются в открытых комментариях.')
 r.p('Передача смены включает открытые заявки, исполнителей, ближайшие дедлайны, ожидаемые ответы и риски. Изменение общей инфраструктуры сопровождается анализом зависимостей, оценкой влияния, согласованным окном, проверками и планом отката. Аварийное изменение для P1 разрешает руководитель поддержки, действия документируются после стабилизации.')
 r.minor('11. Порядок выполнения обращений')
 for text in ['Регистрация: тема, описание, услуга, приоритет, контакт заказчика и связанные КЕ.','Проверка полноты данных, дубликатов и влияния; принятие в работу и назначение исполнителя.','Диагностика связанных ресурсов, выбор плана, согласование рискованных действий.','Восстановление услуги и контрольные проверки; документирование выполненных действий.','Перевод в «Решена» с описанием результата; подтверждение заказчиком и закрытие либо возврат в работу.','Включение результатов в месячный отчёт: реакция, решение, нарушения, простои, причины и корректирующие меры.']:
  r.bullet(text)
 r.p('При нарушении сроков исполнитель уведомляет заказчика и фиксирует причину и корректирующее действие. Учебная модель предусматривает сервисный кредит 5 % стоимости затронутой услуги при доступности от 99,0 % до 99,5 %, 10 % при доступности ниже 99,0 %; суммарный кредит ограничен 20 % её месячной стоимости. Расчёт выполняется после сверки интервалов. Претензия подаётся в течение 10 календарных дней после отчёта, ответ предоставляется в течение 5 дней.')
 r.p('SLA пересматривается ежеквартально и при существенном изменении услуг. Прототип ITSM автоматизирует карточки, роли, историю и сроки. Автоматические интеграции с инфраструктурой, измерение месячной доступности и финансовый расчёт кредитов требуют отдельного внедрения.')
 r.heading('Вывод по работе')
 r.p('Составлено соглашение об уровне сервиса для ООО «ТехноСервис». Определены границы шести услуг, исходные тарифы и единицы оплаты, средства предоставления, четыре приоритета и три уровня поддержки. Установлены круглосуточные сроки реакции и решения, статусы, очередь, эскалация и взаимодействие распределённых команд.')
 r.p('Разработанное SLA связывает каталог и ресурсы предприятия с моделями процессов и реализацией Service Desk. Показатели качества и сервисные кредиты являются условиями учебной модели; их фактическое достижение требует эксплуатационных измерений и договора с заказчиком.')
 return r.save()
if __name__=='__main__':print(build())
